using namespace cg3::cgal::internal;

// Build the Delaunay triangulation
DT dt;
for (const cg3::Point2d& p : points) {
    dt.insert(Point_2(p.x(), p.y()));
}

// Build the Voronoi diagram
VD vd(dt);

// Extract the Voronoi cells
std::vector<std::vector<cg3::Point2d>> result;
result.reserve(points.size());

for (VD::Site_iterator siteIt = vd.sites_begin(); siteIt != vd.sites_end(); ++siteIt) {
    VD::Face_handle face = vd.dual_face(siteIt);
    if (face == VD::Face_handle()) {
        // Handle unbounded cells (empty cell)
        result.emplace_back();
        continue;
    }

    std::vector<cg3::Point2d> cell;
    Ccb_halfedge_circulator ec = face->ccb();
    Ccb_halfedge_circulator done = ec;
    do {
        if (!ec->is_segment()) {
            Point_2 p = ec->source()->point();
            cell.emplace_back(p.x(), p.y());
        }
    } while (++ec != done);

    result.push_back(std::move(cell));
}

return result;

